INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3.414, -416.5, 0.0, 190805, "2025/01/31 12:00:00", 2, "カリン", "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 1, 1, 1000001, 1, "2030/01/01 14:59:59", 62);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3.099, -416.5, 0.0, 190805, "2025/01/31 12:00:00", 2, "カリン", "ミッションをクリアして、\n報酬をゲットしましょう！", 1, 1, 1000002, 2, "2030/01/01 14:59:59", 62);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.801, -416.5, 0.0, 190805, "2025/01/31 12:00:00", 2, "カリン", "受け取ることができる\n報酬があるようです\n確認してみてください", 1, 1, 1000003, 3, "2030/01/01 14:59:59", 63);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (0.0, -416.5, 0.0, 190805, "2025/01/31 12:00:00", 2, "カリン", "報酬がもらえますよ！\nチェックしてみてください", 1, 2, 1000004, 4, "2030/01/01 14:59:59", 63);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.12, -363.0, 0.0, 190805, "2025/01/31 12:00:00", 1, "カリン", "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 1, 2, 1000005, 5, "2030/01/01 14:59:59", 64);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1.68, -363.0, 0.0, 190805, "2025/01/31 12:00:00", 2, "カリン", "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 1, 1, 1000006, 6, "2030/01/01 14:59:59", 64);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.33, -363.0, 0.0, 190805, "2025/01/31 12:00:00", 1, "カリン", "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 1, 2, 1000007, 7, "2030/01/01 14:59:59", 64);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.18, -285.0, -6.0, 133701, "2025/01/31 12:00:00", 7, "ラビリスタ", "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 10201, 3, 1020101, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.77, -285.0, -2.0, 133901, "2025/01/31 12:00:00", 2, "クリスティーナ", "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 10201, 1, 1020102, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (15.5, -285.0, 0.0, 133801, "2025/01/31 12:00:00", 1, "ネネカ", "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 10201, 6, 1020103, 301, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (9.061, -285.0, 0.0, 134301, "2025/02/28 12:00:00", 5, "ランファ", "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 10202, 2, 1020201, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.699, -285.0, 0.0, 134401, "2025/02/28 12:00:00", 2, "チカ", "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 10202, 1, 1020202, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.595, -285.0, 0.0, 134601, "2025/03/31 12:00:00", 2, "アオイ", "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 10203, 1, 1020301, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.758, -285.0, 0.0, 134501, "2025/03/31 12:00:00", 2, "クローチェ", "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 10203, 1, 1020302, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.0, -285.0, 0.0, 132302, "2025/04/30 12:00:00", 6, "ルイズマリー", "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 10204, 2, 1020401, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.904, -285.0, 0.0, 132402, "2025/04/30 12:00:00", 2, "イロハ", "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 10204, 1, 1020402, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.487, -285.0, 0.0, 132502, "2025/04/30 12:00:00", 2, "ソノ", "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 10204, 4, 1020403, 301, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.763, -285.0, 0.0, 134901, "2025/05/31 12:00:00", 2, "カノン", "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 10205, 1, 1020502, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.417, -285.0, 0.0, 134801, "2025/05/31 12:00:00", 3, "ツムギ", "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 10205, 1, 1020503, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (10.335, -285.0, 0.0, 135001, "2025/06/30 12:00:00", 7, "エリス", "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 10206, 3, 1020601, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.281, -285.0, 0.0, 135101, "2025/06/30 12:00:00", 4, "シェフィ", "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 10206, 2, 1020602, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (12.244, -285.0, 0.0, 135201, "2025/06/30 12:00:00", 2, "プレシア", "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 10206, 1, 1020603, 301, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.339, -285.0, 0.0, 135301, "2025/07/31 12:00:00", 8, "クリア", "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 10207, 2, 1020701, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.184, -285.0, 0.0, 135401, "2025/07/31 12:00:00", 9, "アネモネ", "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 10207, 7, 1020702, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3.906, -285.0, 0.0, 129101, "2025/08/31 12:00:00", 2, "アイラ", "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 10208, 9, 1020801, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (14.465, -285.0, 0.0, 129201, "2025/08/31 12:00:00", 2, "シナツ", "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 10208, 1, 1020802, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.662, -285.0, 0.0, 100101, "2025/08/31 12:00:00", 3, "ヒヨリ", "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 10208, 4, 1020803, 301, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (10.915, -285.0, 0.0, 100301, "2025/08/31 12:00:00", 3, "レイ", "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 10208, 1, 1020804, 401, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.042, -285.0, 0.0, 135802, "2025/09/30 12:00:00", 7, "ユキノ", "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 10209, 1, 1020901, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (9.402, -285.0, 0.0, 135903, "2025/09/30 12:00:00", 1, "サツキ", "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 10209, 4, 1020902, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.16, -285.0, 0.0, 136902, "2025/09/30 12:00:00", 1, "ルルィ", "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 10209, 8, 1020903, 301, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.0, -285.0, 0.0, 137401, "2025/10/31 12:00:00", 2, "カスミ", "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 10210, 3, 1021001, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.12, -285.0, 0.0, 136001, "2025/10/31 12:00:00", 1, "アラクネ", "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 10210, 4, 1021002, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.386, -285.0, 0.0, 136202, "2025/10/31 12:00:00", 2, "ナーナ", "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 10210, 4, 1021003, 301, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.438, -285.0, 0.0, 136402, "2025/11/30 12:00:00", 4, "ユイ", "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 10211, 3, 1021101, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.35, -285.0, 0.0, 136302, "2025/11/30 12:00:00", 5, "ミソラ", "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 10211, 1, 1021102, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.0, -285.0, 0.0, 136501, "2025/12/31 12:00:00", 2, "シズル", "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 10212, 1, 1021201, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.25, -285.0, 0.0, 137902, "2025/12/31 12:00:00", 2, "リノ", "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 10212, 1, 1021202, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.5, -285.0, 0.0, 106801, "2025/12/31 12:00:00", 2, "ラビリスタ", "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 10212, 1, 1021203, 301, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.204, -285.0, 0.0, 126501, "2026/01/31 12:00:00", 2, "ライラエル", "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 10213, 1, 1021301, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.176, -285.0, 0.0, 129701, "2026/01/31 12:00:00", 2, "ネフィ＝ネラ", "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 10213, 1, 1021302, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.602, -285.0, 0.0, 133101, "2026/01/31 12:00:00", 5, "ヴァイオレット", "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 10213, 1, 1021303, 301, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (10.14, -285.0, 0.0, 138101, "2026/02/06 12:00:00", 3, "ライラエル", "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 10213, 1, 1021304, 102, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (10.152, -285.0, 0.0, 138201, "2026/02/06 12:00:00", 7, "ネフィ＝ネラ", "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 10213, 1, 1021305, 202, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (9.688, -285.0, 0.0, 138001, "2026/02/06 12:00:00", 3, "ヴァイオレット", "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 10213, 4, 1021306, 302, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.928, -285.0, 0.0, 138301, "2026/02/12 12:00:00", 1, "ペコリーヌ", "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 10213, 2, 1021307, 401, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (9.19, -285.0, 0.0, 138702, "2026/02/28 12:00:00", 2, "ワカナ", "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 10214, 4, 1021401, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.724, -285.0, 0.0, 138802, "2026/02/28 12:00:00", 3, "シオリ", "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 10214, 1, 1021402, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7.758, -285.0, 0.0, 138902, "2026/03/31 12:00:00", 1, "グレイス", "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 10215, 4, 1021501, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.375, -285.0, 0.0, 139002, "2026/03/31 12:00:00", 4, "キョウカ", "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 10215, 6, 1021502, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.173, -285.0, 0.0, 136902, "2026/03/31 12:00:00", 1, "ルルィ", "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 10215, 6, 1021503, 301, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4.202, -285.0, 0.0, 139202, "2026/04/30 12:00:00", 2, "ミホ", "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 10216, 6, 1021601, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2.842, -285.0, 0.0, 139302, "2026/04/30 12:00:00", 1, "マホ", "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 10216, 6, 1021602, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4.598, -285.0, 0.0, 139402, "2026/04/30 12:00:00", 1, "エリカ", "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 10216, 4, 1021603, 301, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.533, -285.0, 0.0, 125802, "2026/05/31 12:00:00", 3, "リリ", "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 10217, 4, 1021701, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.0, -285.0, 0.0, 126102, "2026/05/31 12:00:00", 3, "プレシア", "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 10217, 3, 1021702, 301, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.214, -285.0, 0.0, 126002, "2026/05/31 12:00:00", 4, "クリア", "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 10217, 3, 1021703, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8.781, -285.0, 0.0, 139501, "2026/05/31 12:00:00", 3, "リリ", "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 10217, 1, 1021704, 102, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.529, -285.0, 0.0, 139601, "2026/05/31 12:00:00", 1, "クリア", "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 10217, 2, 1021705, 202, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3.195, -285.0, 0.0, 139701, "2026/05/31 12:00:00", 2, "プレシア", "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 10217, 3, 1021706, 302, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (12.43, -285.0, 0.0, 139902, "2026/06/30 12:00:00", 3, "ルイズマリー", "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 10218, 2, 1021801, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6.35, -285.0, 0.0, 140001, "2026/06/30 12:00:00", 3, "クレジッタ", "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 10218, 2, 1021802, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (10.23, -285.0, 0.0, 140102, "2026/07/31 12:00:00", 5, "フブキ", "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 10219, 1, 1021901, 101, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5.584, -285.0, 0.0, 140201, "2026/07/31 12:00:00", 2, "ヴァンピィ", "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 10219, 1, 1021902, 201, "2030/01/01 14:59:59", 61);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3.414, -416.5, 0.0, 190801, "2026/04/10 12:00:00", 2, "カリン", "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 2, 1, 2000001, 1, "2030/01/01 14:59:59", 62);
